import{_ as a,o as t,c as r,ak as n}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy art and UI brief","description":"Owners: Luis (art), Miguel (UI), Sherwin (experience).\\nThe lesson-collection GDD is the current experience specification.\\nCurrent work prepares documentation and asset/UI requ","frontmatter":{"title":"Chainy art and UI brief","description":"Owners: Luis (art), Miguel (UI), Sherwin (experience).\\nThe lesson-collection GDD is the current experience specification.\\nCurrent work prepares documentation and asset/UI requ","source":"docs/archive/pre-lesson-collection-2026-11-11/design/design-brief.md","category":"Archive","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-lesson-collection-2026-11-11/design/design-brief.md","filePath":"content/docs/archive/pre-lesson-collection-2026-11-11/design/design-brief.md"}'),i={name:"content/docs/archive/pre-lesson-collection-2026-11-11/design/design-brief.md"};function o(s,e,c,l,d,p){return t(),r("div",null,[...e[0]||(e[0]=[n('<div><h1 id="chainy-art-and-ui-brief">Chainy art and UI brief<a class="header-anchor" href="#chainy-art-and-ui-brief" aria-label="Link to this section">​</a></h1><p>Owners: Luis (art), Miguel (UI), Sherwin (experience). The <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">lesson-collection GDD</a> is the current experience specification. Current work prepares documentation and asset/UI requirements; Unity implementation waits for final owner approval.</p><h2 id="current-screen-and-asset-requirements">Current screen and asset requirements<a class="header-anchor" href="#current-screen-and-asset-requirements" aria-label="Link to this section">​</a></h2><p>Prepare main-menu/world cards with sequential locks; tutorial NPC presentation; mobile joystick and Interact; Encyclopedia, Quest, and Pause buttons; lesson panels; required review and save-error states. Each world needs 13 recognizable encounter locations, including three ordered item/NPC/facility sequences. Nine distinct activity scenes may reuse visual components, but their different player rules must remain clear. Use text/icons as well as color for status, show successful saving before recorded completion, and preserve safe return positions. The visual direction below remains a reusable reference; earlier wallet, currency, shop, restoration, and actual-model-training screen details are historical. Create and review mockups before asset production or scene wiring.</p><h2 id="visual-direction">Visual direction<a class="header-anchor" href="#visual-direction" aria-label="Link to this section">​</a></h2><p>Use a fixed orthographic isometric camera, approximately 35–45 degrees top-down, and restrained stylized low-poly art. Environments use faceted silhouettes, simple beveled planes, angular ruins, sparse painterly surface detail, controlled bloom and long readable shadows. Scene composition must read as a playable compact level, with clear routes and small characters at gameplay scale.</p><p>The supplied Tunic screenshots are the reference for camera, lighting, material density and low-poly environment composition. Do not copy their maps, characters, creatures, props, icons or HUD. Avoid voxel-block terrain, bright toy-diorama scenery, rounded animated-film rendering and close third-person framing.</p><p>Keep Chainy&#39;s character identity: blue-haired explorer in yellow, friendly white screen-faced robots and cyan record/block motifs. Translate those designs into the same faceted low-poly language used by the world. The two supplied Chainy images remain identity references:</p><p><img src="/Chainy-Docs/attachments/docs/media/gdd/reference-chainy-01.png" alt="Chainy visual reference"></p><p><a href="/Chainy-Docs/attachments/docs/media/gdd/reference-chainy-02.png">Second visual reference</a>. Their old gameplay details, counts, rounded environment treatment and screen layouts are not current requirements. The BlockForge image and previous generated gameplay diagrams are historical.</p><p><img src="/Chainy-Docs/attachments/docs/media/gdd/current-visuals/isometric-exploration.png" alt="Approved isometric exploration target"></p><p>This mockup governs camera angle, gameplay scale, low-poly environment treatment and scene density. It is a concept, not proof of an implemented level.</p><h2 id="dialogue-and-choice-ui">Dialogue and choice UI<a class="header-anchor" href="#dialogue-and-choice-ui" aria-label="Link to this section">​</a></h2><p>Dialogue remains layered over the live isometric world. Do not load a separate visual-novel scene or replace the background with character art.</p><ul><li>Bottom: one wide translucent dialogue panel with speaker name and current line/question.</li><li>Middle: compact vertically stacked response or answer choices.</li><li>Left and right: waist-up portraits of the Explorer and current guide/speaker, visually integrated with the world.</li><li>Input: world movement and interaction controls are disabled while dialogue is open; only one UI layer accepts taps.</li><li>Feedback: choices remain neutral before submission; use text/icons as well as color after submission.</li><li>Mobile fit: preserve safe areas, readable wrapping and generous touch targets on the smallest supported phone.</li></ul><p><img src="/Chainy-Docs/attachments/docs/media/gdd/current-visuals/dialogue-overlay.png" alt="Approved dialogue overlay target"></p><p>This mockup governs overlay placement. Its blockchain question is illustrative and does not approve the complete question bank, scoring or retry rules.</p><h2 id="small-production-package">Small production package<a class="header-anchor" href="#small-production-package" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Person</th><th>Deliver</th><th>Review</th></tr></thead><tbody><tr><td>Luis</td><td>Low-poly character/robot/prop assets, isometric modular environment pieces, portrait renders, mode icons and simple feedback effects</td><td>Christian checks import/performance and camera fit; Miguel checks screen fit</td></tr><tr><td>Miguel</td><td>Local demo profile, movement/interaction prompts, dialogue/contextual Quiz, wallet review/confirmation, ledger repair, quest log/encyclopedia, results, pause and save-error feedback</td><td>Sherwin checks clarity; Christian checks behavior and input locking</td></tr><tr><td>Sherwin</td><td>W01–W04 / B01–B03 / demo B07 journey, scope gates, screen priorities and learning purpose</td><td>Sean checks instructional wording</td></tr><tr><td>Sean</td><td>Final instructions, definitions, answer explanations and captions</td><td>Sherwin and Christian</td></tr></tbody></table><p>Inspect the existing models reported by Christian before requesting replacements. Reuse only assets that can support the approved isometric low-poly direction without retaining the superseded visual treatment. Make one representative camera-and-level sample first, then complete only the approved inventory. Luis supplies editable files, export settings, naming and source/license notes; do not invent polygon/texture budgets before testing the sample on target Android hardware.</p><h2 id="readability-and-handoff">Readability and handoff<a class="header-anchor" href="#readability-and-handoff" aria-label="Link to this section">​</a></h2><p>Show the objective, available action and result clearly. Pair color with text/icons. Keep essential content usable with audio muted. Test on the smallest available target phone.</p><p>Deliver assets/screens with a preview, source path, import notes, intended use and known gaps. Christian owns shared scenes; Luis and Miguel hand over assets/prefabs without overwriting integration work.</p><p>CH-10 owns the reusable kit; CH-26 owns screens. Use the <a href="/Chainy-Docs/content/docs/media/gdd/gameplay-first/readme.html">v2 concept pack</a> for production handoff: Sean, Matthew and Lee reuse the robot base. Prioritize Web3 workshop/lantern and Blockchain beacon/record props. AI art is conditional/later; standalone Wordle/BlockMatch UI and art are deferred. The core freezes October 30; protect integration/device tests through November 6 and regression/rehearsal November 7–9 before Cryptita Plays community beta testing November 10. Pre-final remains November 21.</p></div>',1)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
